import {readFile,writeFile} from "node:fs/promises";const e=process.env;while(true){try{await readFile(e.DISPATCH_RELEASE_PATH!);break}catch{await Bun.sleep(5)}}const attempt=Number(e.DISPATCH_ATTEMPT),ownerToken=e.DISPATCH_OWNER_TOKEN,laneId=e.DISPATCH_LANE_ID,kind=process.argv[2];await writeFile(e.DISPATCH_ACK_PATH!,JSON.stringify({attempt,ownerToken,at:new Date().toISOString()}));const sha=kind==="synthetic"?"a".repeat(40):Bun.spawnSync(["git","rev-parse","HEAD"]).stdout.toString().trim();const report=kind==="foreign"?`${e.DISPATCH_REPORT_PATH}.foreign`:e.DISPATCH_REPORT_PATH!;await writeFile(report,`lane: ${laneId}\nattempt: ${attempt}\ncommit: ${sha}\nresult: clean\n`);await writeFile(e.DISPATCH_TERMINAL_PATH!,JSON.stringify({laneId,attempt:kind==="attempt"?attempt+1:attempt,ownerToken,at:new Date().toISOString(),reportPath:report,sha,verdict:"clean"}));
